IF InternalInt1 >= IntInput1 AND NOT BoolOutput1 THEN
    {timer:on_delay}.IN := TRUE; // Condition confirmed for enough scans, start on delay
    {timer:off_delay}.IN := FALSE;
ELSIF BoolOutput1 AND InternalInt1 = 0 THEN
    {timer:off_delay}.IN := TRUE; // Output on but condition lost, start off delay
    {timer:on_delay}.IN := FALSE;
ELSE
    {timer:on_delay}.IN := FALSE; // No transition pending, stop both timers
    {timer:off_delay}.IN := FALSE;
END_IF;

IF {timer:on_delay}.Q THEN
    BoolOutput1 := TRUE; // On delay elapsed, condition confirmed
    {timer:on_delay}.IN := FALSE;
    {timer:on_delay}.RESET := TRUE; // Ready for next cycle
END_IF;

IF {timer:off_delay}.Q THEN
    BoolOutput1 := FALSE; // Off delay elapsed, condition lost
    {timer:off_delay}.IN := FALSE;
    {timer:off_delay}.RESET := TRUE; // Ready for next cycle
END_IF;

IF BoolOutput1 THEN
    RealOutput1 := InternalReal1; // Pass scaled value while active
ELSE
    RealOutput1 := 0.0; // Clear when inactive
END_IF;
